#!/usr/bin/env node
/**
 * Attributes the generated bytes of every JS chunk in perf/v3.1/tmp-dist/assets to its original
 * source modules (VLQ-decodes the source map; a generated span belongs to the source of the segment
 * that starts it, like source-map-explorer). Output: perf/v3.1/bundle-modules.json + a console table.
 *   node perf/v3.1/scripts/analyze-sourcemaps.mjs [--top=25]
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { resolve, dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { gzipSync } from 'node:zlib'

const here = dirname(fileURLToPath(import.meta.url))
const v31 = resolve(here, '..')
const assets = join(v31, 'tmp-dist', 'assets')
const top = Number(process.argv.find((a) => a.startsWith('--top='))?.split('=')[1] ?? 25)

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const lookup = new Map([...B64].map((c, i) => [c, i]))
function decodeSegment(str) {
  const out = []
  let value = 0
  let shift = 0
  for (const ch of str) {
    let digit = lookup.get(ch)
    const cont = digit & 32
    digit &= 31
    value += digit << shift
    if (cont) shift += 5
    else {
      const neg = value & 1
      value >>>= 1
      out.push(neg ? -value : value)
      value = 0
      shift = 0
    }
  }
  return out
}

/** Collapse a source path to a package / app module label. */
function label(src) {
  const s = src.replace(/\\/g, '/')
  const nm = s.lastIndexOf('node_modules/')
  if (nm >= 0) {
    const rest = s.slice(nm + 'node_modules/'.length)
    const parts = rest.split('/')
    const pkg = parts[0].startsWith('@') ? parts.slice(0, 2).join('/') : parts[0]
    const file = parts.slice(pkg.split('/').length).join('/')
    return { pkg, file }
  }
  const i = s.indexOf('/src/')
  return { pkg: '(app)', file: i >= 0 ? s.slice(i + 1) : s }
}

const report = {}
for (const f of readdirSync(assets).filter((x) => x.endsWith('.js'))) {
  const code = readFileSync(join(assets, f), 'utf8')
  let map
  try {
    map = JSON.parse(readFileSync(join(assets, f + '.map'), 'utf8'))
  } catch {
    continue
  }
  const lines = code.split('\n')
  const bySource = new Map()
  let srcIdx = 0
  const mLines = map.mappings.split(';')
  for (let li = 0; li < mLines.length; li++) {
    const line = lines[li] ?? ''
    let genCol = 0
    const segs = mLines[li] ? mLines[li].split(',').map(decodeSegment) : []
    const starts = []
    for (const seg of segs) {
      genCol += seg[0]
      if (seg.length >= 4) {
        srcIdx += seg[1]
        starts.push([genCol, srcIdx])
      } else starts.push([genCol, -1])
      // advance the other fields so later segments stay relative (orig line/col/name)
      if (seg.length >= 4) {
        /* line & col deltas do not matter for byte attribution */
      }
    }
    for (let k = 0; k < starts.length; k++) {
      const [c, s] = starts[k]
      const end = k + 1 < starts.length ? starts[k + 1][0] : line.length
      const key = s >= 0 ? map.sources[s] : '(unmapped)'
      bySource.set(key, (bySource.get(key) ?? 0) + Math.max(0, end - c))
    }
  }
  const pkgs = new Map()
  const files = []
  for (const [src, bytes] of bySource) {
    const { pkg, file } = src === '(unmapped)' ? { pkg: '(unmapped)', file: '' } : label(src)
    pkgs.set(pkg, (pkgs.get(pkg) ?? 0) + bytes)
    files.push({ pkg, file, bytes })
  }
  files.sort((a, b) => b.bytes - a.bytes)
  report[f] = {
    raw: code.length,
    gzip: gzipSync(code, { level: 9 }).length,
    packages: Object.fromEntries([...pkgs].sort((a, b) => b[1] - a[1])),
    topFiles: files.slice(0, 80),
    allFiles: files.map((x) => `${x.pkg}/${x.file}`),
  }
}

writeFileSync(join(v31, 'bundle-modules.json'), JSON.stringify(report, null, 1))
for (const [chunk, r] of Object.entries(report).sort((a, b) => b[1].raw - a[1].raw)) {
  if (r.raw < 20000) continue
  console.log(`\n== ${chunk}  raw ${r.raw}  gzip ${r.gzip}`)
  for (const [p, b] of Object.entries(r.packages).slice(0, 12)) console.log(`   ${String(b).padStart(8)}  ${p}`)
  for (const x of r.topFiles.slice(0, top)) console.log(`      ${String(x.bytes).padStart(8)}  ${x.pkg}/${x.file}`)
}
